"use client"

import { useState } from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import { signInWithEmailAndPassword, signInWithPopup } from "firebase/auth"
import { auth, googleProvider } from "@/lib/firebase"
import { Button } from "@/components/ui/Button"
import BackButton from "@/components/shared/BackButton"

export default function LoginPage() {
  const router = useRouter()
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState("")

  const handleEmailLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsLoading(true)
    setError("")

    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password)
      
      // Sync user to PostgreSQL backend
      const token = await userCredential.user.getIdToken(true);
      await fetch("http://localhost:3001/api/v1/users/sync", {
         method: "POST",
         headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${token}`
         },
         body: JSON.stringify({ name: userCredential.user.displayName, email: userCredential.user.email })
      });

      // Redirect to dashboard on success
      router.push("/dashboard")
    } catch (err: any) {
      setError(err.message || "Failed to login. Please check your credentials.")
    } finally {
      setIsLoading(false)
    }
  }

  const handleGoogleLogin = async () => {
    setIsLoading(true)
    setError("")

    try {
      const userCredential = await signInWithPopup(auth, googleProvider)
      
      // Sync user to PostgreSQL backend
      const token = await userCredential.user.getIdToken(true);
      await fetch("http://localhost:3001/api/v1/users/sync", {
         method: "POST",
         headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${token}`
         },
         body: JSON.stringify({ name: userCredential.user.displayName, email: userCredential.user.email })
      });

      // Redirect to dashboard on success
      router.push("/dashboard")
    } catch (err: any) {
      setError(err.message || "Google sign-in failed.")
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="min-h-screen pt-24 md:pt-32 pb-20 px-4 flex items-center justify-center">
      <div className="max-w-md w-full">
        <BackButton className="mb-6 -ml-2" />
        <div className="p-8 bg-white border border-orange-100 rounded-2xl shadow-sm">
            <div className="text-center mb-8">
              <h2 className="font-serif text-3xl font-bold text-orange-950">Welcome Back</h2>
              <p className="mt-2 text-sm text-orange-900/60">
                Securely access your Pinddaan portal.
              </p>
            </div>

            {error && (
              <div className="mb-6 p-4 bg-red-50 text-red-700 text-sm rounded-lg border border-red-100">
                {error}
              </div>
            )}

            <div className="space-y-4">
              <Button 
                onClick={handleGoogleLogin} 
                className="w-full bg-white text-orange-950 border border-orange-200 hover:bg-orange-50 font-medium h-12 flex items-center justify-center gap-3"
                disabled={isLoading}
              >
                <svg viewBox="0 0 24 24" width="20" height="20" xmlns="http://www.w3.org/2000/svg">
                  <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
                  <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                  <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                  <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                </svg>
                Continue with Google
              </Button>

              <div className="relative flex items-center">
                <div className="flex-grow border-t border-orange-100"></div>
                <span className="flex-shrink-0 mx-4 text-orange-900/40 text-sm">or</span>
                <div className="flex-grow border-t border-orange-100"></div>
              </div>

              <form onSubmit={handleEmailLogin} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-orange-950 mb-1">Email Address</label>
                  <input 
                    type="email" 
                    required
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full h-11 px-3 rounded-md border border-orange-200 outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500"
                    placeholder="you@example.com"
                  />
                </div>
                <div>
                  <div className="flex justify-between items-center mb-1">
                    <label className="block text-sm font-medium text-orange-950">Password</label>
                    <Link href="/auth/forgot-password" className="text-sm text-amber-600 hover:text-amber-700">
                      Forgot?
                    </Link>
                  </div>
                  <input 
                    type="password" 
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full h-11 px-3 rounded-md border border-orange-200 outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500"
                    placeholder="••••••••"
                  />
                </div>

                <Button 
                  type="submit" 
                  className="w-full h-12 mt-2 bg-amber-600 hover:bg-amber-700 text-white font-semibold"
                  disabled={isLoading}
                >
                  {isLoading ? "Signing in..." : "Sign In"}
                </Button>
              </form>
            </div>

            <p className="mt-8 text-center text-sm text-orange-900/60">
              Don't have an account?{" "}
              <Link href="/auth/register" className="font-semibold text-amber-600 hover:text-amber-700">
                Create an account
              </Link>
            </p>
        </div>
      </div>
    </div>
  )
}
